DOC7_ITEMS = [{'id': 'TERRA_QA_087', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'community_governance', 'sub_category': 'Mục tiêu và đối tượng Sổ tay phương án ứng phó thiên tai', 'difficulty': 'easy', 'question': 'Mục tiêu ban hành cuốn Sổ tay hướng dẫn xây dựng phương án ứng phó thiên tai theo các cấp độ rủi ro thiên tai (thuộc Dự án Quản lý rủi ro thiên tai VN-Haz/WB5) là gì?', 'ground_truth_context': 'Theo quy định tại điểm a, khoản 4 Điều 22, Luật Phòng chống thiên tai, Ban Chỉ đạo Trung ương về phòng chống thiên tai phối hợp với Ủy ban Quốc gia Tìm kiếm Cứu nạn (nay là Ủy ban Quốc gia Ứng phó sự cố, thiên tai và Tìm kiếm cứu nạn) hướng dẫn xây dựng phương án ứng phó thiên tai theo các cấp độ rủi ro thiên tai. Do vậy, cuốn Sổ tay hướng dẫn này được xây dựng và ban hành nhằm mục đích hướng dẫn Ban Chỉ huy PCTT và TKCN các Bộ, ngành, địa phương, các cơ quan, đơn vị và người dân triển khai xây dựng phương án và các biện pháp ứng phó đối với các loại hình thiên tai trên địa bàn sát với tình hình thiên tai thực tế của từng địa phương, góp phần nâng cao năng lực ứng phó thiên tai của các tổ chức, đơn vị; nâng cao khả năng phối hợp và hỗ trợ của các lực lượng và chính quyền các cấp nhằm hạn chế thiệt hại do thiên tai gây ra, đảm bảo phát triển bền vững.', 'ground_truth_answer': 'Cuốn Sổ tay hướng dẫn này được ban hành theo quy định tại điểm a, khoản 4 Điều 22 Luật Phòng chống thiên tai nhằm hướng dẫn Ban Chỉ huy PCTT và TKCN các Bộ, ngành, địa phương, các cơ quan đơn vị và người dân triển khai xây dựng phương án và các biện pháp ứng phó đối với các loại hình thiên tai sát với thực tế từng địa phương. Qua đó góp phần nâng cao năng lực ứng phó thiên tai của các tổ chức, đơn vị; nâng cao khả năng phối hợp và hỗ trợ giữa các lực lượng và chính quyền các cấp nhằm hạn chế tối đa thiệt hại về người và tài sản, đảm bảo phát triển bền vững.', 'keywords': ['sổ tay', 'WB5', 'Điều 22 Luật PCTT', 'phương án ứng phó', 'cấp độ rủi ro']}, {'id': 'TERRA_QA_088', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'community_governance', 'sub_category': 'Căn cứ pháp lý xây dựng phương án ứng phó rủi ro thiên tai', 'difficulty': 'medium', 'question': 'Những văn bản quy phạm pháp luật và căn cứ pháp lý nền tảng nào được sử dụng để xây dựng Sổ tay phương án ứng phó thiên tai theo cấp độ rủi ro?', 'ground_truth_context': 'Sổ tay được biên soạn dựa trên cơ sở pháp lý:\n- Luật Phòng, chống thiên tai số 33/2013/QH13 ngày 19/6/2013;\n- Luật Đê điều số 79/2006/QH11, ngày 29/11/2006;\n- Chiến lược Quốc gia về phòng chống và giảm nhẹ thiên tai đến năm 2020;\n- Nghị định số 160/NĐ-CP ngày 29/11/2018 của Chính phủ quy định chi tiết, hướng dẫn thi hành một số điều của Luật Phòng, chống thiên tai;\n- Nghị quyết số 120/NQ-CP ngày 17/11/2017 của Chính phủ về phát triển bền vững vùng đồng bằng sông Cửu Long;\n- Quyết định số 44/2014/QĐ-TTg ngày 15/8/2014 của Thủ tướng Chính phủ quy định chi tiết về cấp độ rủi ro thiên tai;\n- Chỉ thị số 03/CT-TTg ngày 03/2/2016 của Thủ tướng Chính phủ về công tác phòng chống thiên tai và tìm kiếm cứu nạn giai đoạn 2016-2020;\n- Công văn số 47/TWPCTT ngày 19/5/2015 của Ban Chỉ đạo Trung ương về phòng, chống thiên tai về việc định hướng xây dựng phương án ứng phó thiên tai theo cấp độ rủi ro thiên tai.', 'ground_truth_answer': 'Sổ tay được biên soạn dựa trên các cơ sở pháp lý chủ yếu gồm: Luật Phòng, chống thiên tai số 33/2013/QH13; Luật Đê điều số 79/2006/QH11; Chiến lược Quốc gia về phòng chống và giảm nhẹ thiên tai đến năm 2020; Nghị định số 160/NĐ-CP ngày 29/11/2018; Nghị quyết số 120/NQ-CP ngày 17/11/2017 về phát triển bền vững ĐBSCL; Quyết định số 44/2014/QĐ-TTg ngày 15/8/2014 của Thủ tướng Chính phủ quy định chi tiết về cấp độ rủi ro thiên tai; Chỉ thị số 03/CT-TTg ngày 03/2/2016; và Công văn số 47/TWPCTT ngày 19/5/2015 của Ban Chỉ đạo Trung ương về phòng, chống thiên tai.', 'keywords': ['cơ sở pháp lý', 'Luật PCTT', 'Luật Đê điều', 'Quyết định 44', 'Nghị định 160']}, {'id': 'TERRA_QA_089', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'risk_assessment_mapping', 'sub_category': 'Khái niệm và mô hình cấu thành rủi ro thiên tai UN-ISDR', 'difficulty': 'medium', 'question': 'Rủi ro thiên tai được định nghĩa như thế nào và công thức UN-ISDR biểu diễn mối tương quan giữa Cường độ thiên tai, Tình trạng dễ bị tổn thương và Năng lực ứng phó ra sao?', 'ground_truth_context': 'Rủi ro thiên tai là thiệt hại mà thiên tai có thể gây ra về người, tài sản, môi trường, điều kiện sống và hoạt động kinh tế - xã hội.\n\nViệc đánh giá rủi ro thiên tai dựa vào nhiều yếu tố, một số yếu tố chính bao gồm: đánh giá nguy cơ thiên tai, đánh giá tính dễ bị tổn thương, đánh giá năng lực ứng phó của cộng đồng và đánh giá mức độ rủi ro, xác định giải pháp khắc phục.\n\nVới mỗi loại hình thiên tai, mức độ rủi ro đối với cộng đồng sẽ có tương quan thuận với cường độ thiên tai, với tình trạng dễ bị tổn thương và tương quan nghịch với năng lực của cộng đồng. Tương quan này theo UN-ISDR có thể được diễn tả một cách tương đối trong công thức dưới đây\n\n> [MÔ TẢ HÌNH ẢNH/SƠ ĐỒ]: Sơ đồ biểu diễn mối quan hệ giữa các yếu tố cấu thành rủi ro thiên tai. Công thức được trình bày như sau:\n> Rủi ro trong thiên tai = (Cường độ thiên tai & Tình trạng dễ bị tổn thương) / Năng lực ứng phó thiên tai\n\n**Cường độ thiên tai:** Là độ mạnh yếu của từng loại hình thiên tai.\n**Tình trạng dễ bị tổn thương:** Được xác định bằng các nhân tố hoặc quá trình vật lý, xã hội, kinh tế và môi trường, làm gia tăng tính nhạy cảm của cộng đồng đối với tác động của thiên tai.\n**Năng lực ứng phó:** Là sự kết hợp của tất cả các nguồn lực sẵn có trong một cộng đồng hoặc tổ chức mà có thể làm giảm mức độ rủi ro, hoặc tác động của thiên tai.\n**Những yếu tố chịu rủi ro:** Là dân cư, tài sản, các hoạt động kinh tế, các dịch vụ công cộng hay bất kỳ những gì đang đặt vào tình thế dễ bị tổn thương do thiên tai tại một khu vực xác định.\n\nNói cách khác, rủi ro trong thiên tai sẽ tăng lên nếu cường độ và tần suất của thiên tai càng lớn và tính dễ bị tổn thương của cộng đồng càng cao. Ngược lại, khi năng lực ứng phó với thiên tai của cộng đồng càng tốt thì làm cho nguy cơ rủi ro thiên tai càng giảm. Do đó, để giảm nhẹ rủi ro trong thiên tai, cộng đồng có thể thực hiện các hoạt động nhằm làm giảm nhẹ tác động của thiên tai, giảm bớt những yếu tố dẫn đến tình trạng dễ bị tổn thương và nâng cao khả năng ứng phó của cộng đồng.', 'ground_truth_answer': 'Rủi ro thiên tai là thiệt hại mà thiên tai có thể gây ra về người, tài sản, môi trường, điều kiện sống và hoạt động kinh tế - xã hội. Theo UN-ISDR, mối quan hệ tương đối được biểu diễn qua công thức: Rủi ro trong thiên tai = (Cường độ thiên tai & Tình trạng dễ bị tổn thương) / Năng lực ứng phó thiên tai. Nghĩa là rủi ro sẽ tăng lên nếu cường độ, tần suất thiên tai càng lớn và tính dễ bị tổn thương của cộng đồng càng cao; ngược lại rủi ro sẽ giảm đi khi năng lực ứng phó của cộng đồng được nâng cao.', 'keywords': ['rủi ro thiên tai', 'công thức UNISDR', 'cường độ', 'dễ bị tổn thương', 'năng lực ứng phó']}, {'id': 'TERRA_QA_090', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'risk_assessment_mapping', 'sub_category': 'Tiêu chí phân định cấp độ rủi ro thiên tai', 'difficulty': 'easy', 'question': 'Các tiêu chí căn bản nào được quy định để xác định và phân cấp độ rủi ro thiên tai?', 'ground_truth_context': 'Cấp độ rủi ro thiên tai là sự phân định mức độ thiệt hại do thiên tai có thể gây ra về người, tài sản, môi trường, điều kiện sống và hoạt động kinh tế - xã hội.\n\nCấp độ rủi ro thiên tai được xác định cho từng loại hình thiên tai và được công bố cùng nội dung bản tin dự báo, cảnh báo về thiên tai.\n\nTiêu chí phân cấp độ rủi ro thiên tai dựa vào:\n\n*   Cường độ hoặc mức độ nguy hiểm của thiên tai.\n*   Phạm vi ảnh hưởng.\n*   Khả năng gây thiệt hại đến tính mạng, tài sản, công trình hạ tầng và môi trường.\n*   Mức độ phơi bày trước thiên tai.\n*   Khả năng ứng phó với thiên tai.', 'ground_truth_answer': 'Cấp độ rủi ro thiên tai là sự phân định mức độ thiệt hại do thiên tai có thể gây ra về người, tài sản, môi trường, điều kiện sống và hoạt động kinh tế - xã hội. Tiêu chí phân cấp độ rủi ro thiên tai dựa vào 5 yếu tố căn bản: 1) Cường độ hoặc mức độ nguy hiểm của thiên tai; 2) Phạm vi ảnh hưởng; 3) Khả năng gây thiệt hại đến tính mạng, tài sản, công trình hạ tầng và môi trường; 4) Mức độ phơi bày trước thiên tai; và 5) Khả năng ứng phó với thiên tai.', 'keywords': ['tiêu chí phân cấp', 'cấp độ rủi ro', 'cường độ', 'phạm vi ảnh hưởng', 'khả năng ứng phó']}, {'id': 'TERRA_QA_091', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'community_governance', 'sub_category': 'Đánh giá năng lực ứng phó theo phương châm 4 tại chỗ', 'difficulty': 'medium', 'question': 'Trong quá trình xây dựng phương án ứng phó, việc đánh giá năng lực ứng phó thiên tai trên cơ sở phương châm "4 tại chỗ" bao gồm những nội dung thu thập thông tin nào?', 'ground_truth_context': '## 4.2. Đánh giá năng lực ứng phó thiên thai (được đánh giá trên cở sở 4 tại chỗ)\n\nNăng lực ứng phó thiên tai của tổ chức, cá nhân là quá trình thu thập, tổng hợp và phân tích thông tin về nguồn lực (con người, cơ sở vật chất, tài chính), giải pháp công trình và phi công trình trên địa bàn gồm:\n\n- Đánh giá các kinh nghiệm kỹ năng sẵn có của mỗi cá nhân, gia đình, cộng đồng có thể thực hiện trước, trong và sau thiên tai theo phương châm 4 tại chỗ.\n- Xác định lực lượng này ở đâu, do ai quản lý, cách sử dụng và tổ chức huy động như thế nào.\n- Năng lực tổ chức di dời sơ tán dân (địa điểm, phương tiện, tổ chức điều hành).\n- Năng lực cứu hộ cứu nạn (con người, phương tiện, trang thiết bị).\n- Hệ thống công trình, cơ sở hạ tầng (nhà kiên cố, đường cứu hộ, hệ thống đê điều...).', 'ground_truth_answer': 'Năng lực ứng phó được đánh giá qua việc thu thập, phân tích thông tin về nguồn lực (con người, cơ sở vật chất, tài chính), giải pháp công trình và phi công trình gồm: Đánh giá kinh nghiệm kỹ năng sẵn có của mỗi cá nhân, gia đình, cộng đồng có thể thực hiện trước, trong và sau thiên tai theo phương châm 4 tại chỗ; Xác định lực lượng này ở đâu, do ai quản lý, cách sử dụng và tổ chức huy động; Năng lực tổ chức di dời sơ tán dân (địa điểm, phương tiện, điều hành); Năng lực cứu hộ cứu nạn (con người, phương tiện, trang thiết bị); và Hệ thống công trình cơ sở hạ tầng (nhà kiên cố, đường cứu hộ, hệ thống đê điều...).', 'keywords': ['năng lực ứng phó', '4 tại chỗ', 'sơ tán dân', 'cứu hộ cứu nạn', 'cơ sở hạ tầng']}, {'id': 'TERRA_QA_092', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'vulnerability_evacuation', 'sub_category': 'Đánh giá tình trạng và các đối tượng dễ bị tổn thương', 'difficulty': 'medium', 'question': 'Thế nào là đánh giá tình trạng dễ bị tổn thương và những nhóm đối tượng, công trình, hoạt động nào cần đặc biệt tách biệt để có biện pháp hỗ trợ?', 'ground_truth_context': '### 4.3. Đánh giá về tình trạng dễ bị tổn thương\n\nĐánh giá về tình trạng dễ bị tổn thương là quá trình thu thập, tổng hợp và phân tích thông tin về dân cư, cơ sở hạ tầng, hoạt động kinh tế văn hóa, xã hội đang ở trong điều kiện an toàn, dễ bị thiệt hại do từng loại thiên tai gây ra.\n\n- Phân tích nguyên nhân dẫn đến tình trạng dễ bị tổn thương.\n- Các thông tin thu thập cần tách biệt đối tượng dễ bị tổn thương nhất, số liệu nam, nữ, người khuyết tật, người già, trẻ em để có biện pháp hỗ trợ phù hợp khi xảy ra thiên tai.\n- Xác định các công trình xung yếu như đê điều, hồ đập, đường, trạm, trại nơi trú ẩn neo đậu của tàu thuyền.\n- Xác định các hoạt động dễ bị tổn thương như đánh bắt thủy hải sản, với củi, gỗ khi có lũ, giao thông qua các ngầm tràn, người ở trên các chòi canh nuôi, trồng thủy sản.', 'ground_truth_answer': 'Đánh giá tình trạng dễ bị tổn thương là quá trình thu thập, tổng hợp và phân tích thông tin về dân cư, cơ sở hạ tầng, hoạt động kinh tế - xã hội đang ở trong điều kiện dễ bị thiệt hại do từng loại thiên tai gây ra. Các thông tin thu thập cần đặc biệt tách biệt: Đối tượng dễ bị tổn thương nhất (số liệu nam, nữ, người khuyết tật, người già, trẻ em) để có biện pháp hỗ trợ sơ tán phù hợp; Các công trình xung yếu (đê điều, hồ đập, đường sá, trạm xá, nơi trú ẩn neo đậu tàu thuyền); và Các hoạt động dễ tổn thương (đánh bắt thủy hải sản, vớt củi gỗ trên sông khi lũ, lưu thông qua ngầm tràn, chòi canh nuôi trồng thủy sản).', 'keywords': ['dễ bị tổn thương', 'đối tượng DBTT', 'người già', 'trẻ em', 'khuyết tật', 'ngầm tràn']}, {'id': 'TERRA_QA_093', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'risk_assessment_mapping', 'sub_category': 'Nội dung thể hiện trên Bản đồ rủi ro thiên tai tác chiến', 'difficulty': 'hard', 'question': 'Bản đồ rủi ro thiên tai (bản đồ tác chiến) dùng trong chỉ huy ứng phó tại chỗ cần thể hiện đầy đủ những thông tin và khu vực trọng điểm nào?', 'ground_truth_context': '## 4.5. Lập bản đồ rủi ro thiên tai\n\nKhi xây dựng phương án ứng phó thiên tai cần được thể hiện trên bản đồ hoặc bản sơ họa (hay là bản đồ tác chiến) và thường xuyên cập nhật, bổ sung thông tin vào bản đồ để phục vụ công tác chỉ đạo, chỉ huy ứng phó. Bản đồ hoặc bản sơ họa được treo tại các ban chỉ huy PCTT và TKCN các cấp hoặc một số nơi công cộng để có thể theo dõi được dễ dàng. Trên cơ sở tài liệu thu thập được tiến hành vẽ bản đồ rủi ro thiên tai để chủ động ứng phó với các tình huống thiên tai.\n\nBản đồ hoặc bản sơ họa cần thể hiện các nội dung sau:\n- Xác định danh sách các cơ quan chỉ huy, tên, điện thoại các đồng chí phụ trách các lĩnh vực;\n- Khoanh vùng hoặc tô mầu các khu vực bị ảnh hưởng trực tiếp, các khu vực bị ảnh hưởng gián tiếp theo các màu khác nhau;\n- Xác định vị trí các khu neo đậu tàu thuyền, các khu trú tránh bão an toàn;\n- Xác định các vùng dự kiến phải sơ tán (số lượng/số nhân khẩu cần sơ tán);\n- Xác định các địa điểm, vị trí sơ tán đến;\n- Xác định vị trí trọng điểm, xung yếu của các công trình, cơ sở hạ tầng quan trọng cần phải được bảo vệ;\n- Xác định vị trí, địa điểm các nguồn lực sẽ được huy động (số lượng phương tiện, vật tư, lương thực, nhu yếu phẩm; vị trí tập kết các nguồn lực này tại đâu?\n- Xác định các tuyến đường huyết mạch giữa các thôn/xã và giữa các huyện để thuận tiện trong quá trình chỉ đạo, di chuyển;\n- Phương án cứu hộ, cứu nạn;\n- Thể hiện các nội dung khác (nếu có);\n- Hàng năm tổ chức diễn tập phòng chống bão với các kịch bản có thể xảy ra.', 'ground_truth_answer': 'Bản đồ rủi ro thiên tai cần thể hiện các nội dung: Danh sách cơ quan chỉ huy, tên và số điện thoại cán bộ phụ trách các lĩnh vực; Khoanh vùng/tô màu các khu vực bị ảnh hưởng trực tiếp và gián tiếp theo màu sắc quy định; Vị trí neo đậu tàu thuyền, khu trú tránh bão an toàn; Vùng dự kiến phải sơ tán dân (số lượng hộ/nhân khẩu) và địa điểm sơ tán đến; Vị trí xung yếu, trọng điểm của các công trình cơ sở hạ tầng cần bảo vệ; Vị trí tập kết các nguồn lực huy động (phương tiện, vật tư, lương thực, nhu yếu phẩm); Tuyến đường giao thông huyết mạch phục vụ chỉ đạo di chuyển; Phương án cứu hộ, cứu nạn; và tổ chức diễn tập hàng năm theo các kịch bản.', 'keywords': ['bản đồ rủi ro', 'bản đồ tác chiến', 'khoanh vùng', 'điểm sơ tán', 'tuyến đường huyết mạch']}, {'id': 'TERRA_QA_094', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'community_governance', 'sub_category': 'Mục tiêu và phương pháp lập phương án từ dưới lên', 'difficulty': 'medium', 'question': 'Mục tiêu và nguyên tắc xây dựng phương án ứng phó thiên tai từ cấp cơ sở lên cấp tỉnh được tổ chức theo phương pháp nào?', 'ground_truth_context': '### 5.1. Mục tiêu\n\nKhi xây dựng phương án cần nêu được các mục tiêu của phương án, thể hiện được các nội dung sau:\n\n- Huy động các nguồn lực để chủ động ứng phó có hiệu quả trước mọi tình huống thiên tai có thể xảy ra trong phạm vi quản lý, hạn chế đến mức thấp nhất thiệt hại về người, tài sản, tài nguyên thiên nhiên, môi trường, di sản văn hóa, cơ sở hạ tầng và các công trình trọng yếu do thiên tai có thể gây ra, góp phần quan trọng phát triển bền vững kinh tế - xã hội của ngành và địa phương.\n- Các đơn vị, địa phương trên địa bàn được phân công, chủ động xây dựng phương án ứng phó để làm cơ sở xây dựng phương án ứng phó thiên tai ở cấp cao hơn nhằm ứng phó kịp thời, đạt hiệu quả với từng tình huống cụ thể do thiên tai gây ra.\n- Đảm bảo an toàn về người và tài sản của nhân dân, chủ động sơ tán dân ra khỏi vùng nguy hiểm, hạn chế thấp nhất mọi rủi ro gây ra.\n- Bảo vệ các công trình quan trọng về an ninh Quốc gia, phòng, chống thiên tai, công trình trọng điểm trên địa bàn được phân công, đảm bảo các công trình giao thông, thông tin liên lạc hoạt động thông suốt.\n- Bảo đảm an ninh trật tự vùng bị thiên tai.\n\n### 5.2. Phương pháp và nguyên tắc xây dựng phương án\n\nPhương pháp chính của việc lập Phương án là xây dựng từ dưới lên (từ cấp cơ sở lên) theo sơ đồ hình 1.\n\n> [MÔ TẢ HÌNH ẢNH/SƠ ĐỒ]: Hình ảnh là một sơ đồ khối (flowchart) mô tả phương pháp lập phương án ứng phó với thiên tai, có tiêu đề "SƠ ĐỒ LẬP PHƯƠNG ÁN".\n>\n> Các khối trong sơ đồ và mối quan hệ:\n> 1.  **UBND xã, phường:** Đây là điểm khởi đầu của quy trình từ cấp cơ sở.\n> 2.  **UBND huyện, TP:** Nhận thông tin từ "UBND xã, phường" thông qua mũi tên chỉ lên.\n> 3.  **Sở, ban, ngành:** Nhận thông tin từ "UBND huyện, TP" thông qua mũi tên chỉ sang.\n> 4.  **UBND tỉnh:** Nhận thông tin từ "UBND huyện, TP" và "Sở, ban, ngành" thông qua các mũi tên chỉ lên và chỉ sang.\n>\n> Các mũi tên được chú thích:\n> *   Mũi tên liền nét chỉ lên hoặc sang ngang: "Quan hệ từ dưới lên"\n> *   Mũi tên nét đứt chỉ lên hoặc sang ngang: "Quan hệ phối hợp"\n>\n> Sơ đồ thể hiện một quy trình lập phương án từ cấp thấp nhất (xã, phường) lên cấp cao hơn (huyện, thành phố), sau đó đến các sở, ban, ngành và cuối cùng là cấp tỉnh, với sự phối hợp giữa các cấp.', 'ground_truth_answer': 'Mục tiêu là huy động tối đa các nguồn lực chủ động ứng phó hiệu quả, hạn chế thấp nhất thiệt hại về người và tài sản, chủ động sơ tán dân khỏi vùng nguy hiểm, bảo vệ công trình trọng điểm an ninh quốc gia và duy trì thông suốt giao thông liên lạc. Nguyên tắc xây dựng phương án được thực hiện theo phương pháp từ dưới lên (từ cấp cơ sở lên): bắt đầu từ UBND cấp xã/phường xây dựng phương án cơ sở, gửi lên UBND cấp huyện/thành phố tổng hợp, phối hợp với các sở, ban, ngành chuyên môn, và hoàn thiện trình UBND cấp tỉnh phê duyệt.', 'keywords': ['mục tiêu phương án', 'phương pháp từ dưới lên', 'xã lên huyện tỉnh', 'phối hợp liên ngành']}, {'id': 'TERRA_QA_095', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'typhoon_flood', 'sub_category': 'Khung nội dung phương án và thời điểm ứng phó bão ATNĐ', 'difficulty': 'hard', 'question': 'Nội dung cơ bản của phương án ứng phó thiên tai theo cấp độ rủi ro gồm các bước nào và bão/ATNĐ được phân chia thành những thời điểm ứng phó nào?', 'ground_truth_context': '### 5.4. Nội dung phương án ứng phó với thiên tai theo cấp độ rủi ro thiên tai\n\nNội dung phương án ứng phó với thiên tai theo cấp độ rủi ro thiên tai bao gồm:\n*   Xác định thời điểm ứng phó.\n*   Xác định các kịch bản ứng phó thiên tai.\n*   Xác định đối tượng/phạm vi ảnh hưởng theo từng thời điểm.\n*   Đề xuất các phương án, giải pháp ứng phó tương ứng với các kịch bản.\n*   Một số điểm lưu ý trong phương án (Lưu ý cho các vùng, miền đặc trưng).\n\nTheo Quyết định số 44/2014/QĐ-TTg ngày 15/8/2014 của Thủ tướng Chính phủ, cấp độ rủi ro thiên tai được quy định theo 15 nhóm loại hình thiên tai, mặt khác loại hình thiên tai lũ quét và sạt lở, sụt lún đất do mưa lũ hoặc dòng chảy; hạn hán và xâm nhập mặn thường đi liền với nhau cho nên phương án ứng phó với thiên tai theo cấp độ rủi ro thiên tai sẽ được xây dựng theo 13 nhóm loại hình thiên tai này.\n\n### 5.4.1. Hướng dẫn xây dựng phương án ứng phó với bão, ATNĐ\n\n**Bước 1: Thời điểm ứng phó với bão, ATNĐ**\n\nKhi có tin bão (ATNĐ) cần xác định thời điểm ứng phó, gồm:\n\n*   Tin bão, (ATNĐ) gần biển Đông di chuyển nhanh, có khả năng gây nguy hiểm cho các hoạt động trên biển Đông.\n*   Tin bão, (ATNĐ) trên biển Đông.\n*   Tin bão, (ATNĐ) gần bờ.\n*   Tin bão khẩn cấp (bão đổ bộ vào đất liền).\n*   Tin bão (ATNĐ) trên đất liền.\n*   Tin cuối cùng về bão (ATNĐ).', 'ground_truth_answer': 'Nội dung phương án ứng phó gồm: Xác định thời điểm ứng phó; Xác định các kịch bản ứng phó; Xác định đối tượng, phạm vi ảnh hưởng theo từng thời điểm; Đề xuất phương án, giải pháp ứng phó tương ứng với các kịch bản; và Một số điểm lưu ý đặc thù vùng miền. Khi có bão hoặc áp thấp nhiệt đới (ATNĐ), các thời điểm ứng phó được phân định gồm: 1) Tin bão/ATNĐ gần biển Đông di chuyển nhanh; 2) Tin bão/ATNĐ trên biển Đông; 3) Tin bão/ATNĐ gần bờ; 4) Tin bão khẩn cấp (bão đổ bộ đất liền); 5) Tin bão/ATNĐ trên đất liền; và 6) Tin cuối cùng về bão/ATNĐ.', 'keywords': ['nội dung phương án', 'thời điểm ứng phó', 'bão khẩn cấp', 'kịch bản ứng phó']}, {'id': 'TERRA_QA_096', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'community_governance', 'sub_category': 'Trách nhiệm và nhiệm vụ ứng phó bão của Ban Chỉ huy cấp xã', 'difficulty': 'medium', 'question': 'Trong tình huống bão, áp thấp nhiệt đới, Ban Chỉ huy PCTT&TKCN cấp xã phải khẩn trương triển khai các biện pháp ứng phó cụ thể nào đối với tàu thuyền và phương tiện?', 'ground_truth_context': 'iii) Cấp xã:\n- Thực hiện các công điện, thông báo, chỉ đạo của cấp trên;\n- Thực hiện các phương án ứng phó về:\n    + Thông tin truyền thông về cơn bão (ATNĐ);\n    + Theo dõi, nắm bắt thông tin về tàu thuyền, phương tiện đang hoạt động trên biển: Số lượng phương tiện, người ở trên phương tiện, vị trí hoạt động, nắm bắt liên lạc thường xuyên,...;\n    + Phối hợp với các Đồn, Trạm biên phòng thông tin tới các phương tiện tàu, tàu du lịch, thuyền và các phương tiện đang hoạt động trên biển biết về vị trí, hướng di chuyển và diễn biến của bão, ATNĐ để chủ động các biện pháp phòng tránh;\n    + Thông tin tới gia đình và chủ phương tiện; liên lạc thường xuyên với tàu thuyền đang hoạt động trên biển', 'ground_truth_answer': 'Cấp xã phải: Thực hiện nghiêm các công điện, thông báo chỉ đạo của cấp trên; Thông tin truyền thông kịp thời về diễn biến bão/ATNĐ; Theo dõi, nắm bắt số lượng tàu thuyền, số lao động trên tàu, vị trí và giữ liên lạc thường xuyên; Phối hợp với các Đồn, Trạm biên phòng thông tin tới các phương tiện tàu bè, tàu du lịch để chủ động di chuyển phòng tránh; Thông tin tới gia đình và chủ phương tiện; và duy trì liên lạc thường xuyên với tàu thuyền đang hoạt động trên biển.', 'keywords': ['cấp xã', 'ứng phó bão', 'tàu thuyền', 'đồn biên phòng', 'thông tin liên lạc']}, {'id': 'TERRA_QA_097', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'first_aid_survival', 'sub_category': 'Huy động lực lượng hậu cần tại chỗ khắc phục hậu quả thiên tai', 'difficulty': 'hard', 'question': 'Công tác chỉ đạo huy động lực lượng, phương tiện và hậu cần tại chỗ để ứng phó và khắc phục hậu quả thiên tai, lũ quét, sạt lở đất gồm những nhiệm vụ ưu tiên nào?', 'ground_truth_context': 'Lực lượng, phương tiện và hậu cần tại chỗ:\n\n*   Huy động lực lượng, phương tiện để cứu chữa kịp thời những người bị thương; người bị thương nặng phải được chuyển nhanh lên tuyến trên để cứu chữa; khẩn trương tìm kiếm những người còn mất tích;\n*   Huy động lực lượng để sơ tán, di chuyển những người còn sống sót tới nơi an toàn; dựng lều bạt; cứu trợ khẩn cấp các điều kiện thiết yếu cho đồng bào; động viên, thăm hỏi, chia sẻ đau thương mất mát, hỗ trợ kịp thời về vật chất và tinh thần cho những người bị mất người thân, mất mát tài sản;\n*   Huy động lực lượng phối hợp với cộng đồng thôn, bản và thân nhân người bị nạn thực hiện việc chôn cất người bị chết theo phong tục của địa phương và thực hiện kịp thời hỗ trợ mai táng phí;\n*   Thống kê, đánh giá mức độ thiệt hại thực tế, đối chiếu chính sách hiện hành quy định hiện hành để trình Trưởng Ban chỉ đạo Trung ương về PCTT hoặc Chính phủ xét, quyết định mức cứu trợ khẩn cấp cho các gia đình bị thiệt hại do thiên tai gây ra;\n*   Tổ chức khắc phục hậu quả do lũ quét, sạt lở đất gây ra, gồm:\n    *   Hệ thống thông tin liên lạc phải được ưu tiên hàng đầu để chính quyền ở cấp cơ sở báo cáo được tình hình thiệt hại do thiên tai gây ra trên địa bàn và những yêu cầu cần được cứu hộ, cứu nạn, cứu trợ khẩn cấp;\n    *   Hệ thống giao thông, cầu cống và đường dân sinh đảm bảo cho công tác cứu hộ, cứu nạn, công tác cứu trợ khẩn cấp có thể tiếp cận sớm nhất với đồng bào vùng bị thiên tai;\n    *   Dọn dẹp vệ sinh môi trường, đặc biệt là môi trường để phòng tránh dịch bệnh phát sinh. Khi phát hiện có dấu hiệu của dịch bệnh phải tập trung lực lượng, phương tiện khoanh vùng, bao vây, dập tắt dịch trong thời gian ngắn nhất, hạn chế lây lan ra cộng đồng;\n*   Thực hiện cứu hộ, cứu nạn đối với người, công trình và cơ sở hạ tầng khu vực bị thiệt hại;\n*   Triển khai lực lượng đảm bảo an ninh trật tự khu vực bị thiệt hại.', 'ground_truth_answer': 'Các nhiệm vụ ưu tiên gồm: Huy động lực lượng, phương tiện cứu chữa kịp thời người bị thương (chuyển nặng lên tuyến trên) và khẩn trương tìm kiếm người mất tích; Sơ tán người sống sót tới nơi an toàn, dựng lều bạt, cứu trợ khẩn cấp lương thực nhu yếu phẩm thiết yếu, thăm hỏi hỗ trợ tinh thần và vật chất; Phối hợp với gia đình và thôn bản tổ chức mai táng và hỗ trợ mai táng phí; Thống kê thiệt hại trình cấp thẩm quyền hỗ trợ; Ưu tiên hàng đầu khôi phục hệ thống thông tin liên lạc để báo cáo chỉ đạo cứu trợ; Khôi phục đường giao thông, cầu cống dân sinh để tiếp cận cứu nạn; Dọn dẹp vệ sinh môi trường phòng ngừa dịch bệnh bùng phát; Cứu hộ công trình và triển khai lực lượng giữ gìn an ninh trật tự.', 'keywords': ['hậu cần tại chỗ', 'cứu trợ khẩn cấp', 'tìm kiếm người mất tích', 'thông tin liên lạc', 'vệ sinh môi trường']}, {'id': 'TERRA_QA_098', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'landslide_flashflood', 'sub_category': 'Những lưu ý cốt lõi ứng phó lũ quét và sạt lở đất', 'difficulty': 'medium', 'question': 'Những lưu ý trọng tâm khi xây dựng phương án ứng phó với lũ quét và sạt lở đất tại các khu vực xung yếu là gì?', 'ground_truth_context': 'Những lưu ý khi xây dựng phương án ứng phó với lũ quét, sạt lở đất\n\nLũ quét, sạt lở đất là loại hình thiên tai xảy ra bất ngờ, phạm vi hẹp nhưng sức tàn phá lớn và thường gây thiệt hại nghiêm trọng về người và tài sản. Tuy chưa dự báo được loại hình thiên tai này nhưng có thể chủ động phòng tránh bằng cách khoanh vùng những nơi có nguy cơ cao xảy ra lũ quét, sạt lở đất, đặc biệt là trong các trường hợp mưa lớn nhiều ngày hoặc các hình thế thời tiết khác. Do vậy, phương án ứng phó với lũ quét, sạt lở đất cần phải chú trọng đến các nội dung:\n\n## a) Xây dựng bản đồ, khoanh vùng các điểm có nguy cơ cao về lũ quét, sạt lở đất, tai biến địa chất, trên bản đồ thể các nội dung:\n\n*   Xác định các vị trí theo các màu khác nhau;\n*   Xác định số hộ/nhân khẩu tại các vị trí đã khoanh vùng;\n*   Xác định lực lượng tại chỗ các khu vực đã khoanh vùng (dân quân tự vệ, xung kích, quân đội, công an khu vực,...);\n*   Xác định các nguồn lực (phương tiện, vật tư,...) tại các vị trí đã khoanh vùng để có thể huy động khi cần thiết;\n*   Xác định các tuyến đường giữa các thôn/bản để thuận tiện trong công tác chỉ đạo, chỉ huy hiện trường và sơ tán dân khi cần thiết.\n\n## b) Chú trọng công tác tuyên truyền, phổ biến kiến thức, kỹ năng ứng phó tới tận thôn bản để người dân hiểu, nắm bắt thông tin về rủi ro thiên tai do lũ quét, sạt lở đất.\n\n## c) Đảm bảo thông tin liên lạc giữa các thôn/bản với cơ quan chỉ đạo chỉ huy để xử lý các sự cố.\n\n## d) Cắm các biển cảnh báo, bố trí lực lượng ứng trực để kiểm soát, ngăn chặn người, phương tiện tại các vị trí sạt lở đất đá và ở các ngầm qua sông, suối khi có mưa lũ lớn, kéo dài nhiều ngày.\n\n## đ) Chú trọng phương án tìm kiếm cứu nạn, cứu hộ sớm nhất có thể ngay sau khi lũ quét, sạt lở đất xảy ra để hạn chế thiệt hại về người, tài sản do thiên tai gây ra.', 'ground_truth_answer': 'Do lũ quét và sạt lở đất xảy ra bất ngờ, sức tàn phá dữ dội và chưa thể dự báo chính xác, phương án cần chú trọng: a) Xây dựng bản đồ khoanh vùng các điểm nguy cơ cao (phân màu, xác định số hộ/nhân khẩu, điểm sơ tán an toàn); b) Chú trọng tuyên truyền, phổ biến kiến thức kỹ năng ứng phó đến tận thôn bản; c) Đảm bảo thông tin liên lạc thông suốt giữa thôn bản với ban chỉ đạo chỉ huy; d) Cắm biển cảnh báo và bố trí lực lượng canh gác kiểm soát nghiêm ngặt ngăn chặn người và phương tiện qua lại các vị trí sạt lở và ngầm tràn khi mưa lũ lớn; đ) Chú trọng phương án tìm kiếm cứu nạn sớm nhất có thể ngay sau khi thiên tai xảy ra.', 'keywords': ['lũ quét', 'sạt lở đất', 'khoanh vùng nguy cơ', 'ngầm tràn', 'biển cảnh báo', 'TKCN']}, {'id': 'TERRA_QA_099', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'typhoon_flood', 'sub_category': 'Chỉ đạo vận hành an toàn hồ chứa và bảo đảm tính mạng trong lũ lụt', 'difficulty': 'medium', 'question': 'Trong tình huống mưa lũ lớn và ngập lụt, cấp tỉnh và cấp huyện cần thực hiện công tác chỉ đạo ứng phó thế nào đối với hồ chứa và an toàn người dân vùng trũng thấp?', 'ground_truth_context': 'Chỉ đạo việc phân công nhiệm vụ cho các đơn vị nắm chắc địa bàn, căn cứ vào bản tin dự báo, cảnh báo và tình hình diễn biến cụ thể của lũ, ngập lụt để triển khai các công việc ứng phó;\n- Chỉ đạo đơn vị quản lý hồ chứa thực hiện nghiêm quy trình vận hành hồ chứa đã được duyệt;\n- Chỉ đạo công tác sẵn sàng lực lượng để kịp thời cứu hộ, cứu nạn đối với vùng trung thấp, vùng có nguy cơ bị ngập lũ, các trọng điểm đối với các công trình phòng chống lũ (đê, kè, cống, hồ chứa,...).\n\nb) Cấp huyện:\n- Chỉ đạo, thực hiện công tác trực ban, theo dõi chặt chẽ diễn biến của mưa lũ và tình hình ngập lụt; thông tin, chỉ đạo từ Ban Chỉ đạo Trung ương về Phòng chống thiên tai và công điện của tỉnh;\n- Chỉ đạo công tác phòng, tránh ứng phó với lũ và ngập lụt:\n    + Nội dung về truyền thông tới cấp huyện, xã;\n    + Nội dung về ứng phó đảm bảo an toàn cho người trong vùng bị ảnh hưởng của lũ, ngập lụt;\n    + Nội dung về ứng phó đối với dân cư vùng ngập lụt nhất là đối với các đối tượng dễ bị tổn thương như trẻ em, người già, người dân mưu sinh trong vùng lũ như không vớt củi, không đi qua các vũng trũng thấp, vùng dòng lũ chảy xiết, vùng ngập lụt, trẻ em', 'ground_truth_answer': 'Cấp tỉnh chỉ đạo phân công nhiệm vụ bám sát địa bàn theo diễn biến mưa lũ; chỉ đạo đơn vị quản lý hồ chứa thực hiện nghiêm quy trình vận hành hồ chứa đã được duyệt; chỉ đạo sẵn sàng lực lượng cứu hộ đê điều, hồ chứa, công trình trọng điểm. Cấp huyện thực hiện trực ban 24/24, theo dõi sát diễn biến ngập lụt, truyền thông xuống xã; triển khai ứng phó đảm bảo an toàn tính mạng nhân dân vùng lũ, đặc biệt đối với đối tượng dễ bị tổn thương (trẻ em, người già) và các hoạt động nguy hiểm như cấm người dân vớt củi, không đi qua các vùng trũng thấp, vùng dòng lũ chảy xiết; bảo vệ mùa màng và khu nuôi trồng thủy sản.', 'keywords': ['vận hành hồ chứa', 'an toàn đê điều', 'ngập lụt', 'vùng trũng thấp', 'không vớt củi']}, {'id': 'TERRA_QA_100', 'source_document': 'a6cdc8f0e8ee43b19e884d0ee89d5474.md', 'category': 'risk_assessment_mapping', 'sub_category': 'Quy trình các bước xây dựng phương án và phân tích điều kiện tự nhiên', 'difficulty': 'medium', 'question': 'Ba bước cơ bản để xây dựng phương án ứng phó thiên tai theo cấp độ rủi ro và các yếu tố tự nhiên cần phân tích ở bước chuẩn bị gồm những gì?', 'ground_truth_context': 'CÁC BƯỚC XÂY DỰNG ÁN ỨNG PHÓ THIÊN TAI THEO CẤP ĐỘ RRTT\n\nBước 1: Thu Thập phân tích thông tin.\nBước 2: Thực hiện đánh giá rủi ro thiên tai và tổng hợp phân tích kết quả đánh giá.\nBước 3: Xây dựng phương án ứng phó thiên tai theo các cấp độ rủi ro thiên tai.\n\n# 3. CHUẨN BỊ XÂY DỰNG PHƯƠNG ÁN\n\n## 3.1. Thu thập thông tin về điều kiện tự nhiên:\n\nVị trí địa lý và đặc điểm địa hình phải phân tích được các yếu tố liên quan đến thiên tai trên địa bàn, lĩnh vực quản lý: Sông ngòi, địa hình dốc, khu trũng thấp, khu vực hay bị sạt trượt; điều kiện địa hình tác động đến khí hậu tạo ra các loại thiên tai theo đặc trưng vùng (núi cao, thung lũng...); các khu vực bị phơi bày trước thiên tai ( Cửa sông, ven biển, ven sông suối..); các loại hình thiên tai do yếu tố địa hình, địa chất thường xảy ra trên địa bàn, lĩnh vực quản lý.', 'ground_truth_answer': 'Ba bước cơ bản gồm: Bước 1: Thu thập phân tích thông tin; Bước 2: Thực hiện đánh giá rủi ro thiên tai và tổng hợp phân tích kết quả đánh giá; Bước 3: Xây dựng phương án ứng phó thiên tai theo các cấp độ rủi ro thiên tai. Ở bước chuẩn bị, việc thu thập thông tin về điều kiện tự nhiên cần phân tích: Vị trí địa lý, đặc điểm địa hình (sông ngòi, địa hình dốc, khu trũng thấp, khu vực hay bị sạt trượt); Điều kiện địa hình tác động khí hậu tạo thiên tai đặc trưng vùng (núi cao, thung lũng...); Các khu vực bị phơi bày trước thiên tai (cửa sông, ven biển, ven sông suối); và Các loại hình thiên tai do địa hình, địa chất thường xảy ra trên địa bàn quản lý.', 'keywords': ['các bước xây dựng phương án', 'điều kiện tự nhiên', 'địa hình', 'sông ngòi', 'chuẩn bị']}]
